from typing import List

class Node:
    '''Simple node (No duplicate edges between nodes)'''
    def __init__(self, id: int, out_edges: List[int]):
        uniques = set()
        for edge in out_edges:
            if edge in uniques:
                raise RuntimeError("Duplicate edge detected")
            uniques.add(edge)
        self.id = id
        self.out_edges = out_edges

class Graph:
    '''Simple directed graph (No duplicate edges between nodes, no duplicate nodes)'''
    def __init__(self, nodes: List[Node]):
        uniques = set()
        for node in nodes:
            if node in uniques:
                raise RuntimeError("Duplicate node detected")
            uniques.add(node)
        self.nodes = nodes

    def find_node(self, id: int):
        for node in self.nodes:
            if node.id == id:
                return node

    def topological_sort(self) -> List[Node]:
        # Build adjacency list
        adj = {node.id: [] for node in self.nodes}
        in_degree = {node.id: 0 for node in self.nodes}

        for node in self.nodes:
            for edge in node.out_edges:
                adj[node.id].append(edge)
                in_degree[edge] += 1

        # Initialize queue with nodes of in-degree 0
        queue = [node.id for node in self.nodes if in_degree[node.id] == 0]
        result = []

        while queue:
            current = queue.pop(0)
            result.append(current)
            for neighbor in adj[current]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(result) != len(self.nodes):
            raise RuntimeError("Graph has cycles and cannot be topologically sorted")

        return [self.find_node(node) for node in result]

