import string

def prepare_line(line):
    for char in string.punctuation:
        line = line.replace(char, "")
    for char in string.digits:
        line = line.replace(char, "")
    return line

def vowel_count(line):
    vowel_count = 0
    diphthongs = ["ae", "oe", "ei", "ea", "ia", "io", "aea"]
    i = 0
    while i < len(prepare_line(line)):
        if i + 1 < len(prepare_line(line)) and prepare_line(line)[i:i+2] in diphthongs:
            i += 2
            continue
        if prepare_line(line)[i] in "aeiouy":
            vowel_count += 1
        i += 1
    return vowel_count

