def translate_element(element: Union[str, HTMLElement]) -> str:
    if isinstance(element, str):
        return element
    else:
        child_content: List[str] = [translate_element(child) for child in element.content]
        if element.name == 'h1':
            return f"# {''.join(child_content)}"
        elif element.name == 'h2':
            return f"## {''.join(child_content)}"
        elif element.name == 'h3':
            return f"### {''.join(child_content)}"
        elif element.name == 'h4':
            return f"#### {''.join(child_content)}"
        elif element.name == 'h5':
            return f"##### {''.join(child_content)}"
        elif element.name == 'h6':
            return f"###### {''.join(child_content)}"
        elif element.name == 'p':
            return ''.join(child_content)
        elif element.name == 'div':
            return '\n'.join(child_content)
        elif element.name == 'ol':
            items = child_content
            if len(items) > 5:
                items = items[:5] + [f'<a href="/see-more">see more</a>']
            return '\n'.join(items)
        elif element.name == 'ul':
            items = child_content
            if len(items) > 5:
                items = items[:5] + [f'<a href="/see-more">see more</a>']
            return '\n'.join(items)
        else:
            return ""

