    curr_max = lst[0]
    start_idx = 0
    end_idx = 0
    for i in range(1, len(lst)):
        if curr_max < lst[i]:
            curr_max = lst[i]
            start_idx = i
        else:
            curr_max += lst[i]
        if curr_max > max_so_far:
