class Manager:
    def __init__(self, name: str, direct_reports: List[Union["Manager", "IC"]]):
        self.name = name
        self.team = direct_reports

    def find_manager_n(self, name: str, n: int) -> List[str]:
        if n < 1:
            return []
        return self._find_manager_n_helper(name, n, [self.name])

    def _find_manager_n_helper(self, name: str, n: int, path: List[str]) -> List[str]:
        if n == 1:
            return [path[-1]] if path[-1] == name else []

        managers = []
        for direct_report in self.team:
            if isinstance(direct_report, Manager):
                managers.extend(direct_report._find_manager_n_helper(name, n - 1, path + [self.name]))
            elif direct_report.name == name:
                managers.append(path[-1])
        return managers

