                    temp_board = [row[:] for row in board]
                    temp_board[i][j] = True
                    if self.checkWin(temp_board, True):
                        return (i, j)
        # Check for blocking opponent's win
        for i in range(3):
            for j in range(3):
                if board[i][j] is None:
                    # Simulate placing 'False' (player 2) at (i, j)
                    temp_board = [row[:] for row in board]
                    temp_board[i][j] = False
                    if self.checkWin(temp_board, False):
                        return (i, j)
        # If no winning or blocking move, choose a corner if available
        if board[0][0] is None:
            return (0, 0)
        elif board[0][2] is None:
            return (0, 2)
        elif board[2][0] is None:
            return (2, 0)
        elif board[2][2] is None:
            return (2, 2)
        # If no corners are available, choose center if available
        elif board[1][1] is None:
            return (1, 1)
        # If no moves left, return any empty cell (though this should not happen in a valid game)
        for i in range(3):
            for j in range(3):
                if board[i][j] is None:
                    return (i, j)
        return (0, 0)

    def checkWin(self, board: List[List[bool]], player: bool) -> bool:
        # Check rows
        for i in range(3):
            if all(board[i][j] == player for j in range(3)):
                return True
        # Check columns
        for j in range(3):
            if all(board[i][j] == player for i in range(3)):
                return True
        # Check diagonals
        if all(board[i][i] == player for i in range(3)):
            return True
        if all(board[i][2-i] == player for i in range(3)):
            return True
        return False

