from typing import Optional
import numpy as np
from autograd import grad

class integrator:
    def __init__(self, lower: float, upper: float, stepsize: float): 
        self.lower = lower
        self.upper = upper
        self.stepsize = stepsize

    def rectangle_left(self, f):
        result = 0
        x = self.lower
        while x < self.upper:
            result += f(x) * self.stepsize
            x += self.stepsize
        return result

    def rectangle_right(self, f):
        result = 0
        x = self.lower + self.stepsize
        while x <= self.upper:
            result += f(x) * self.stepsize
            x += self.stepsize
        return result

    def rectangle_middle(self, f):
        result = 0
        x = self.lower + self.stepsize / 2
        while x < self.upper:
            result += f(x) * self.stepsize
            x += self.stepsize
        return result

    def M_search(self, f, num_points: Optional[int] = 100) -> float:
        second_derivative = grad(grad(f))
        x = np.linspace(self.lower, self.upper, num_points)
        return max(np.abs(second_derivative(x)))

    def middle_error(self, f):
        M = self.M_search(f) 
        return M * (self.upper - self.lower)**3  / (24 * self.stepsize**2 )

    def determine_stepsize_middle(self, f, error: float) -> int:
        M = self.M_search(f)
        return int(np.sqrt((M * (self.upper - self.lower)**3) / (24 * error))) + 1

    def trapezoid(self, f):
        result = 0
        x = self.lower
        while x < self.upper:
            result += (f(x) + f(x + self.stepsize)) * self.stepsize / 2
            x += self.stepsize
        return result

    def trapezoid_error(self, f):
        M = self.M_search(f)
        return M * (self.upper - self.lower)**3 / (12  * self.stepsize**2) 

    def determine_stepsize_trapezoid(self, f, error: float) -> int:
        M = self.M_search(f)
        return int(np.sqrt((M * (self.upper - self.lower)**3) / (12 * error))) + 1

    def simpson(self, f):
        n = len(np.linspace(self.lower, self.upper, int(1 / self.stepsize) + 1))
        if n % 2 != 2:
            raise ValueError("Number of intervals must be even for Simpson's rule.")
        h = self.upper - self.lower
        x = np.linspace(self.lower, self.upper, n)
        integral = (h / 3) * (f(x[0]) + 4 * np.sum(f(x[1::2])) + 2 * np.sum(f(x[2::2])) + f(x[-1]))
        return integral

import pandas as pd

class StringOperations:
    """A class containing a series of string operations"""

    def remove_duplicates(text):
        """Returns the text with only unique characters"""
        unique = []
        for char in text:
            if char not in unique:
                unique.append(char)
        return ''.join(unique)

    def word_reversal(text):
        """Returns the text with words reversed"""
        sentences = text.split(' ')
        return ' '.join(reversed(sentences))

    def remove_vowels(text):
        """Returnes the text with vowels removed"""
        vowels = 'aeiou'
        return ''.join(char for char in text if char.lower() not in vowels)

def calculate_all_properties(text, functions):
    properties = [func(text) for func in functions]
    return properties

def multi_apply(data, col, colnames, functions):
    properties = data[col].apply(calculate_all_properties, functions=functions)
    properties_columns = pd.DataFrame(properties.tolist(), columns=colnames)
    return pd.concat([data, properties_columns], axis=1)

import math

def gcd(a : int, b : int) -> int:
    """Compute the Greatest Common Divisor (GCD) of a and b."""
    assert a > 0 and b > 0
    while b != 0:
        a, b = b, a % b
    return a

def euler_totient(n : int) -> int:
    """Compute the Euler's Totient function of n."""
    assert n > 0 
    if n == 1 : return 1
    count = 0
    for i in range(1, n):
        if gcd(i, n) == 1:
            count += 1
    return count

def powermod(base : int, exp : int, mod : int) -> int:
    """Compute a^b mod c using successive squaring."""
    if exp == 0:
        return 1 % mod
    if exp % 2 == 0:
        temp = powermod(base, exp // 2, mod)
        return (temp * temp) % mod
    else:
        return (base * powermod(base, exp - 1, mod)) % mod

def check_coprime_euler(a : int, b : int):
    assert a > 0 and b > 0
    return powermod(a, euler_totient(b), b) == 1

import random

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

class EllipticCurve:
    def __init__(self, a : int, b : int, p : int):
        self.a = a 
        self.b = b
        assert is_prime(p), "p is not prime"
        self.p = p # prime

    def is_on_curve(self, x : int, y : int) -> bool:
        return (y**2 - x**3 - self.a*x - self.b) % self.p == 0

    def mod_inverse(self, value: int) -> int:
        """ uses fermat's little theorem for modular inverse """
        return pow(value, self.p - 2, self.p)

    def point_addition(self, P: tuple, Q: tuple) -> tuple:
        """ returns the sum of the two points, P, Q 
            uses (None, None) to represent infinity """
        # cases where either point are infinity
        if P == (None, None) : return Q
        if Q == (None, None) : return P

        # P + (-P) = 0 or if the y coordinate is 0, return point at infinity
        if P[0] == Q[0] and (P[1] != Q[1] or P[1] == 0) : return (None, None)

        if P != Q:
            # The lambda (slope) calculation for two distinct points
            m = (Q[1] - P[1]) * self.mod_inverse(Q[0] - P[0] + self.p) % self.p
        else:
            # The lambda (slope) calculation for point doubling
            m = (3 * P[0]**2 + self.a) * self.mod_inverse(2 * P[1]) % self.p

        x_r = (m**2 - P[0] - Q[0]) % self.p
        y_r = (m * (P[0] - x_r) - P[1]) % self.p

        return (x_r, y_r)

    def point_double(self, P: tuple) -> tuple:
        """ double the given point """
        return self.point_addition(P, P)

    def windowed_point_multiplication(self, k: int, P: tuple, w: int = 4) -> tuple:
        """ Computes elliptic curve point multiplication using the windowing method. """
        # Precompute all 2^w powers of the point P
        precomputed = [P]
        for _ in range(w - 1):
            precomputed.append(self.point_double(precomputed[-1]))

        # Convert k to binary
        binary_k = bin(k)[2:]
        result = (None, None)  # Identity element
        index = 0

        for bit in binary_k:
            if bit == '1':
                result = self.point_addition(result, precomputed[index])
            index += 1
            if index >= len(precomputed):
                index = 0

        return result

    def point_multiplication(self, k: int, P: tuple) -> tuple:
        """scalar multiplication of P by k."""
        if P == (None, None) or k == 0:
            return (None, None)

        result = (None, None)  # Initialize result as the identity element (infinity point)
        addend = P

        while k:
            if k & 1:
                result = self.point_addition(result, addend)
            addend = self.point_addition(addend, addend)
            k >>= 1

        return result

    def generate_keypair(self, G: tuple, n: int, d : int) -> tuple:
        """ Given an initial point G and an order n, construct a keypair, and d, the private key """
        assert 1 <= d and d <= n-1
        Q = self.windowed_point_multiplication(d, G) # public key
        return (d, Q) 

    def validate_keypair(self, d: int, Q: tuple, G: tuple, n: int) -> bool:
        """ Validate the given keypair, given an initial point G,
            a public key Q, a private key d, and a group order n """
        if not (1 <= d < n) : return False
        if not self.is_on_curve(Q[0], Q[1]) : return False
        return self.windowed_point_multiplication(d, G) == Q

def value_iteration(p: Policy, v: StateValue, theta: float):
    """
    Runs value iteration to find the optimal policy and state value.
    The policy and state value are updated in place. Theta controls the
    convergence of the algorithm, where the algorithm stops when the
    maximum change in the state value is less than theta.
    """
    while True:
        delta = 0
        new_v = [row[:] for row in v]  # Create a copy to avoid overwriting during iteration

        for i, row in enumerate(p):
            for j, col in enumerate(row):
                s = (i, j)
                if col != "TERM":
                    max_a_val = -float('inf')
                    for a in actions:
                        s_next = next_state(s, a)
                        i_next, j_next = s_next
                        r = -1
                        scaled = r + v[i_next][j_next]
                        if scaled > max_a_val:
                            max_a_val = scaled
                    new_v[i][j] = max_a_val

        # Compute delta based on the new values
        for i in range(len(v)):
            for j in range(len(v[i])):
                delta = max(delta, abs(v[i][j] - new_v[i][j]))

        v = new_v  # Update the state values

        if delta < theta:
            break

    for i, row in enumerate(p):
        for j, col in enumerate(row):
            s = (i, j)
            if col != "TERM":
                max_a = []
                max_a_val = -float('inf')
                for a in actions:
                    s_next = next_state(s, a)
                    i_next, j_next = s_next
                    r = -1
                    scaled = r + v[i_next][j_next]
                    if scaled > max_a_val:
                        max_a_val = scaled
                        max_a = [a]
                    elif scaled == max_a_val:
                        max_a.append(a)
                p[i][j] = max_a

import math

def permutation(n, r):
    return int(math.factorial(n) / math.factorial(n - r))

def combination(n, r):
    return int(math.factorial(n) / (math.factorial(r) * math.factorial(n - r)))

def arrangement_unlimited_rep(n, r):
    return int(n ** r)


def combination_unlimited_rep(n, r):
    return int(combination(n + r - 1, n))


def arrangement_restricted_rep(n, rList):
    product = 1

    for r in rList:
        product *= math.factorial(r)

    return int(math.factorial(n) / product)

from typing import Literal, List

Token = Literal["expr", ";", "if", "(", ")", "other", "e"]
NonTerminal = Literal["stmt", "optexpr"]

class ParseTree:
    def __init__(self, children, nonterminal: NonTerminal):
        self.children = children
        self.nonterminal = nonterminal

    def __eq__(self, obj) -> bool:
        if not isinstance(obj, ParseTree):
            return False
        if isinstance(obj, ParseTree) and obj.nonterminal != self.nonterminal:
            return False
        else:
            if len(self.children) != len(obj.children):
                return False
            else:
                for i, child in enumerate(obj.children):
                    if child != self.children[i]:
                        return False
            return True


class Parser:
    Malformed = ValueError("input is not in the language accepted by this grammar")

    def __init__(self):
        self.inputs = []
        self.lookahead = 0

    def parse(self, inputs: List[Token]) -> ParseTree:
        self.inputs = inputs
        self.lookahead = 0
        temp = self.stmt()
        if self.lookahead != len(self.inputs):
            raise Parser.Malformed
        else:
            return temp

    def match(self, terminal: Token):
        if terminal == self.inputs[self.lookahead]:
            self.lookahead += 1
        else:
            raise Parser.Malformed

    def stmt(self) -> ParseTree:
        if self.inputs[self.lookahead] == "expr":
            self.match("expr")
            self.match(";")
            return ParseTree(["expr", ";"], "stmt")
        elif self.inputs[self.lookahead] == "if":
            self.match("if")
            self.match("(")
            self.match("expr")
            self.match(")")
            child = self.stmt()
            return ParseTree(["if", "(", "expr", ")", child], "stmt")
        elif self.inputs[self.lookahead] == "for":
            self.match("for")
            self.match("(")
            optexpr1 = self.optexpr()
            if self.inputs[self.lookahead] != ")":
                self.match(";")
            optexpr2 = self.optexpr()
            if self.inputs[self.lookahead] != ")":
                self.match(";")
            optexpr3 = self.optexpr()
            self.match(")")
            child = self.stmt()
            return ParseTree(["for", "(", optexpr1, ";", optexpr2, ";", optexpr3, ")", child], "stmt")
        elif self.inputs[self.lookahead] == "other":
            self.match("other")
            return ParseTree(["other"], "stmt")
        else:
            raise Parser.Malformed

    def optexpr(self) -> ParseTree:
        if self.inputs[self.lookahead] == "e":
            self.match("e")
            return ParseTree(["e"], "optexpr")
        else:
            child = self.expr()
            return ParseTree([child], "optexpr")

from typing import List


class Matrix:
    def __init__(self, content: List[List[int]]) -> None:
        num_cols = None
        for row in content:
            if num_cols is None:
                num_cols = len(row)
            else:
                if len(row) != num_cols:
                    raise ValueError
        self.content = content

    def transpose(self) -> None:
        new_content = [
            [0 for i in range(len(self.content))] for i in range(len(self.content[0]))
        ]
        for row in range(len(self.content)):
            for col in range(len(self.content[row])):
                new_content[col][row] = self.content[row][col]
        self.content = new_content

    def determinant(self) -> int:
        assert len(self.content) == len(self.content[0])

        if len(self.content) == 2:
            return (
                self.content[0][0] * self.content[1][1]
                - self.content[0][1] * self.content[1][0]
            )
        elif len(self.content) == 3:
            t = self.content
            return (
                t[0][0] * (t[1][1] * t[2][2] - t[1][2] * t[2][1])
                - t[1][0] * (t[0][1] * t[2][2] - t[0][2] * t[2][1])
                + t[2][0] * (t[0][1] * t[1][2] - t[0][2] * t[1][1])
            )
        else:
            raise NotImplementedError

